import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
for term in ['multiple sclerosis methylprednisolone psychosis hallucinations case report','corticosteroid induced psychosis multiple sclerosis relapse treatment review']:
 r=requests.get(u,params={'db':'pubmed','term':term,'retmode':'json','retmax':5},timeout=20)
 ids=r.json()['esearchresult']['idlist']
 print('QUERY:',term,'PMIDS:',ids)
 if ids:
  s=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids: print(i,s[i].get('title',''),s[i].get('pubdate',''))
